import math

def positional_encoding(pos, d):
    pe = []
    for i in range(d):
        angle = pos / 10000 ** ((2 * (i // 2)) / d)
        if i % 2 == 0:
            pe.append(math.sin(angle))
        else:
            pe.append(math.cos(angle))
    return pe

# --- demo (do not change) ---
print([round(x, 4) for x in positional_encoding(1, 4)])
